  height: 100%;
  margin-right: -1px;
}

.ck.ck-content.ck-ai-form__content-field {
  & h2 {
    font-size: 1.3em;
  }

  & h3 {
    font-size: 1.2em;
  }

  & h4, & h5, & h6 {
    font-size: 1.1em;
  }

  & h2, & h3, & h4, & h5, & h6, & p, & ul, & ol {
    margin-block: .5em;
    line-height: 1.7em;
  }

  & > :first-child {
    margin-top: 0;
  }

  & > :last-child {
    margin-bottom: 0;
  }
}

:root, :host {
  --ck-ai-form-view-width: 600px;
  --ck-ai-form-content-height: 175px;
  --ck-ai-form-content-background: var(--ck-color-base-foreground);
  --ck-ai-form-history-font-size: .9em;
  --ck-ai-form-error-background: hsla(from var(--ck-color-feedback-error) h s l / .1);
}

.ck .ck-ai-form {
  width: var(--ck-ai-form-view-width);
  max-width: 100%;

  @media screen and (width <= 600px) {
    --ck-ai-form-view-width: 100vw;
  }

  & .ck-ai-form-content {
    padding: var(--ck-spacing-padding-comfortable);
    width: 100%;

    & .ck-input {
      width: 100%;
    }

    & .ck-ai-form__content-area-wrapper {
      width: 100%;
      max-height: var(--ck-ai-form-content-height);
      border: var(--ck-border-control);
      border-radius: var(--ck-border-radius-control);
      overflow-y: auto;

      &:focus {
        border: var(--ck-focus-ring);
        box-shadow: var(--ck-focus-shadow), 0 0;
        outline: none;
      }
    }

    & .ck-ai-form__content-area {
      background-color: var(--ck-ai-form-content-background);
      display: flex;

      &.ck-ai-form__content-area--processing {
        --ck-color-text: var(--ck-input-disabled-text-color);
        background-color: var(--ck-input-disabled-background-color);
      }

      & .ck-ai-form__content-field {
        white-space: normal;
        width: 100%;
        padding: var(--ck-spacing-padding-tight) var(--ck-spacing-padding);
        min-height: calc(var(--ck-line-height-base) * var(--ck-font-size-base));
        box-sizing: content-box;

        [dir="ltr"] & {
          padding-right: 0;
        }

        [dir="rtl"] & {
          padding-left: 0;
        }

        & > * {
          white-space: normal;
          color: inherit;
        }
      }

      & .ck-spinner-container {
        [dir="ltr"] & {
          margin-right: var(--ck-spacing-gap);
        }

        [dir="rtl"] & {
          margin-left: var(--ck-spacing-gap);
        }
      }

      & .ck-ai-form__copy-button-wrapper {
        flex-direction: column-reverse;
        padding-left: 2px;
        display: flex;
      }

      & .ck-ai-form__copy-button {
        min-height: unset;
        min-width: unset;
        padding: 4px;
        position: sticky;
        bottom: 1px;
        right: 1px;

        & svg {
          --ck-icon-size: 16px;
        }

        &.ck-ai-form__copy-button--copied {
          color: inherit;
        }
      }
    }

    & .ck-ai-form__toolbar {
      margin-top: var(--ck-spacing-gap);
      margin-bottom: calc(2 * var(--ck-spacing-gap));
      border: none;
      padding: 0;
    }

    & .ck-ai-form__loader {
      align-items: center;
      display: flex;

      & .ck-spinner {
        box-sizing: border-box;
      }
    }

    & .ck-autocomplete {
      justify-content: space-between;
      display: flex;

      & > .ck-labeled-field-view {
        flex-grow: 1;
      }

      & > .ck.ck-ai-form__submit {
        [dir="ltr"] & {
          margin-left: var(--ck-spacing-gap);
        }

        [dir="rtl"] & {
          margin-right: var(--ck-spacing-gap);
        }

        border-color: var(--ck-ai-form-submit-button-border-color);
        color: var(--ck-ai-form-submit-button-text-color);

        &.ck-disabled {
          border-color: var(--ck-ai-form-submit-button-disabled-border-color);
        }
      }

      & > .ck-labeled-field-view .ck-ai-form__toggle-history {
        font-size: var(--ck-font-size-xs);
        position: absolute;

        [dir="ltr"] & {
          right: var(--ck-spacing-base);
        }

        [dir="rtl"] & {
          left: var(--ck-spacing-base);
        }

        bottom: var(--ck-spacing-sm);
        top: var(--ck-spacing-sm);
        min-height: unset;
        min-width: unset;
        padding: 4px;
      }

      & .ck-textarea {
        [dir="ltr"] & {
          padding-right: 30px;
        }

        [dir="rtl"] & {
          padding-left: 30px;
        }

        @media screen and (width <= 600px) {
          --ck-input-width: auto;
        }
      }

      & .ck-search__results .ck-list .ck-list__group {
        grid-column-gap: 0px;
        grid-row-gap: 0px;
        grid-template-rows: auto;
        grid-template-columns: auto 1fr;
        display: grid;

        & > span {
          grid-area: 1 / 1 / 2 / 2;
        }

        & > .ck-button {
          min-height: auto;
          font-size: var(--ck-ai-form-history-font-size);
          margin: var(--ck-spacing-gap) 0 0;
          background: none;
          grid-area: 1 / 2 / 2 / 3;
          justify-self: start;
          padding: 0;

          & .ck-button__label {
            line-height: inherit;

            &:hover {
              text-decoration: underline;
            }
          }
        }

        & > .ck-list {
          grid-area: 2 / 1 / 3 / 3;

          & .ck-list__item .ck-button .ck-button__label {
            white-space: nowrap;
            text-overflow: ellipsis;
            max-width: 100%;
            font-size: var(--ck-ai-form-history-font-size);
            line-height: var(--ck-line-height-base);
            overflow: hidden;
          }
        }
      }
    }
  }

  & .ck-ai-form__error {
    padding: var(--ck-spacing-padding);
    background-color: var(--ck-ai-form-error-background);
    color: var(--ck-color-base-text);
    border-radius: var(--ck-border-radius-control);
    margin-bottom: var(--ck-spacing-gap);
    justify-content: center;
    align-items: center;
    display: flex;
  }
