  --ck-comment-content-font-family: var(--ck-font-face, var(--ck-font-family));
  --ck-comment-content-font-size: var(--ck-font-size-md);
  --ck-comment-content-font-color: var(--ck-color-text);
  --ck-comment-context-border-color: var(--ck-color-base-attention);
  --ck-comment-thread-line-size: 1px;
  --ck-comment-border-radius: var(--ck-border-radius-surface);
}

.ck .ck-comment__wrapper {
  font-size: var(--ck-font-size-normal, var(--ck-font-size-base));
  transition: all var(--ck-transition-duration-control-emphasized) linear;
  outline: 0;
  position: relative;

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }

  &:first-of-type {
    border-top-right-radius: var(--ck-comment-border-radius);
    border-top-left-radius: var(--ck-comment-border-radius);
  }

  &:focus {
    background: var(--ck-comment-focus-background-color);
  }

  &:has( + .ck-thread__comment-count) {
    & .ck-comment {
      &:after {
        height: calc(100% - var(--ck-user-avatar-size) - var(--ck-spacing-padding)
					+ var(--ck-size-control-min-height) /* Comment count button height */);
      }
    }
  }
}

.ck .ck-comment {
  &:after {
    content: "";
    opacity: 1;
    left: calc(var(--ck-spacing-standard, var(--ck-spacing-base)) + ( var(--ck-user-avatar-size) / 2 )

			/* Half width of line. */
			- calc(var(--ck-comment-thread-line-size) / 2)
			/* Avatar margin size) */
			+ 2px);
    width: var(--ck-comment-thread-line-size);
    background-color: var(--ck-color-comment-separator, var(--ck-comment-separator-color));
    top: calc(var(--ck-user-avatar-size) + (2 * var(--ck-spacing-padding, var(--ck-spacing-sm))));
    height: calc(100% - var(--ck-user-avatar-size) - var(--ck-spacing-padding));
    border-radius: var(--ck-comment-border-radius);
    display: block;
    position: absolute;
